        return Err(());
    }
    let ResolvedExprKind::Binary {
        op: BinaryOp::Lt,
        left,
        right,
    } = &condition.kind
    else {
        return Err(());
    };
    if !place_is(left, counter) || !place_is(right, length) || condition.ty != ResolvedType::Bool {
        return Err(());
    }
    let ResolvedExprKind::Block {
        statements: iteration,
        tail: iteration_tail,
    } = &body.kind
    else {
        return Err(());
    };
