        binding: row_index,
        mutable: false,
        value: index_snapshot,
        ..
    }, ResolvedStatement::Let {
        binding: discarded,
        mutable: false,
        value: authored,
        ..
    }, ResolvedStatement::Assign {
        binding: incremented,
        field: None,
        value: increment,
        ..
    }] = iteration.as_slice()
    else {
        return Err(());
    };
