        return Err(());
    }
    let ids = [
        &owner.root,
        &length.id,
        &counter.id,
        &row_index.id,
        &discarded.id,
    ];
    if ids
        .iter()
        .enumerate()
        .any(|(index, id)| ids[..index].contains(id))
    {
        return Err(());
    }
    let ResolvedExprKind::Binary {
        op: BinaryOp::Add,
        left,
        right,
    } = &increment.kind
    else {
        return Err(());
    };
    if !place_is(left, counter) || !usize_value(right, 1) {
        return Err(());
    }
    Ok(Some(Prefix {
        source,
        owner,
        element,
        counter,
        length,
        row_index,
        authored,
    }))
